result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "units.py", "content": """"Dimensional-analysis mini-library for medication math education.

Base units: mg, g, mcg, kg (mass); mL, L (volume).
Compound units arise naturally from quantity division/multiplication,
e.g. mg / mL -> mg/mL, and cancel like algebraic variables:
25 mg/kg * 18 kg -> 450 mg.
"""
from __future__ import annotations

import math

__all__ = ["Quantity", "UnitError", "dose_volume"]


class UnitError(Exception):
    """Raised for unknown units or dimensionally incompatible operations."""


# Conversion factor of each named unit to its canonical family unit
# (mass -> mg, volume -> mL).
_FACTORS = {
    "mcg": 1e-3,
    "mg": 1.0,
    "g": 1e3,
    "kg": 1e6,
    "mL": 1.0,
    "L": 1e3,
}
_FAMILY = {
    "mcg": "mass",
    "mg": "mass",
    "g": "mass",
    "kg": "mass",
    "mL": "volume",
    "L": "volume",
}


def _parse_unit(text):
    """Parse a unit string like 'mg', 'mL' or 'mg/kg' into {base: exponent}."""
    if not isinstance(text, str) or not text.strip():
        raise UnitError(f"invalid unit: {text!r}")
    unit = {}
    for i, segment in enumerate(text.split("/")):
        name = segment.strip()
        if name not in _FACTORS:
            raise UnitError(f"unknown unit {name!r}")
        unit[name] = unit.get(name, 0) + (-1 if i else 1)
    return unit


def _format_unit(unit):
    num = [b for b in sorted(unit) if unit[b] > 0]
    den = [b for b in sorted(unit) if unit[b] < 0]

    def term(base):
        power = abs(unit[base])
        return base if power == 1 else f"{base}^{power}"

    s = "*".join(term(b) for b in num)
    if den:
        s += "/" + "/".join(term(b) for b in den)
    return s


class Quantity:
    """A numeric amount tied to a (possibly compound) unit."""

    def __init__(self, value, unit):
        self.value = float(value)
        self.unit = _parse_unit(unit)

    # -- internals -------------------------------------------------------
    @property
    def _factor(self):
        return math.prod(_FACTORS[b] ** e for b, e in self.unit.items())

    @property
    def _signature(self):
        """Dimension signature keyed by physical family, ignoring scale."""
        sig = {}
        for base, exp in self.unit.items():
            fam = _FAMILY[base]
            sig[fam] = sig.get(fam, 0) + exp
        return frozenset((f, e) for f, e in sig.items() if e != 0)

    @property
    def _canonical(self):
        return self.value * self._factor

    @classmethod
    def _create(cls, canonical_value, unit):
        return cls(canonical_value / math.prod(_FACTORS[b] ** e
                                               for b, e in unit.items()),
                   unit)

    # -- arithmetic ------------------------------------------------------
    def _check_add(self, other, op):
        if not isinstance(other, Quantity):
            return NotImplemented
        if self._signature != other._signature:
            raise UnitError(
                f"cannot {op} {_format_unit(self.unit)} and "
                f"{_format_unit(other.unit)}: incompatible dimensions")
        return other

    def __add__(self, other):
        other = self._check_add(other, "add")
        return Quantity(self._canonical + other._canonical, self.unit)

    __radd__ = __add__

    def __sub__(self, other):
        other = self._check_add(other, "subtract")
        return Quantity(self._canonical - other._canonical, self.unit)

    def __neg__(self):
        return Quantity(-self.value, self.unit)

    def __mul__(self, other):
        if isinstance(other, Quantity):
            merged = dict(self.unit)
            for base, exp in other.unit.items():
                merged[base] = merged.get(base, 0) + exp
                if merged[base] == 0:
                    del merged[base]          # dimensional cancellation
            if not merged:
                return self._canonical * other._canonical
            return Quantity._create(self._canonical * other._canonical,
                                    merged)
        if isinstance(other, (int, float)):
            return Quantity(self.value * other, self.unit)
        return NotImplemented

    __rmul__ = __mul__

    def __truediv__(self, other):
        if isinstance(other, Quantity):
            merged = dict(self.unit)
            for base, exp in other.unit.items():
                merged[base] = merged.get(base, 0) - exp
                if merged[base] == 0:
                    del merged[base]          # dimensional cancellation
            if not merged:
                return self._canonical / other._canonical
            return Quantity._create(self._canonical / other._canonical,
                                    merged)
        if isinstance(other, (int, float)):
            return Quantity(self.value / other, self.unit)
        return NotImplemented

    def __rtruediv__(self, other):
        raise UnitError("cannot divide a plain number by a Quantity")

    # -- comparisons / repr ----------------------------------------------
    def __eq__(self, other):
        if not isinstance(other, Quantity):
            return NotImplemented
        return (self._signature == other._signature
                and math.isclose(self._canonical, other._canonical,
                                 rel_tol=1e-9, abs_tol=1e-12))

    def __hash__(self):
        return hash((self._signature, round(self._canonical, 9)))

    def __repr__(self):
        return f"Quantity({self.value:g}, '{_format_unit(self.unit)}')"


def dose_volume(dose_mg_per_kg, weight_kg, concentration_mg_per_ml):
    """Weight-based dose: mg/kg * kg = mg, then mg / (mg/mL) = mL."""
    dose = Quantity(dose_mg_per_kg, "mg/kg") * Quantity(weight_kg, "kg")
    return dose / Quantity(concentration_mg_per_ml, "mg/mL")
